-- V90.cw: Advanced manufacturing costing and yield optimization.
CREATE TABLE IF NOT EXISTS manufacturing_batch_cost (cost_id TEXT PRIMARY KEY,organization_id TEXT NOT NULL,entity_id TEXT NOT NULL,batch_id TEXT NOT NULL,product_id TEXT NOT NULL,period_key TEXT NOT NULL,planned_qty NUMERIC NOT NULL DEFAULT 0,good_qty NUMERIC NOT NULL DEFAULT 0,rework_qty NUMERIC NOT NULL DEFAULT 0,wastage_qty NUMERIC NOT NULL DEFAULT 0,byproduct_qty NUMERIC NOT NULL DEFAULT 0,material_cost NUMERIC NOT NULL DEFAULT 0,packaging_cost NUMERIC NOT NULL DEFAULT 0,labor_cost NUMERIC NOT NULL DEFAULT 0,overhead_cost NUMERIC NOT NULL DEFAULT 0,rework_cost NUMERIC NOT NULL DEFAULT 0,total_cost NUMERIC NOT NULL DEFAULT 0,cost_per_kg NUMERIC NOT NULL DEFAULT 0,cost_per_pack NUMERIC NOT NULL DEFAULT 0,yield_pct NUMERIC NOT NULL DEFAULT 0,standard_cost NUMERIC NOT NULL DEFAULT 0,variance_value NUMERIC NOT NULL DEFAULT 0,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,UNIQUE(organization_id,entity_id,batch_id));
CREATE TABLE IF NOT EXISTS manufacturing_cost_adjustment (adjustment_id TEXT PRIMARY KEY,organization_id TEXT NOT NULL,entity_id TEXT NOT NULL,batch_id TEXT NOT NULL,adjustment_type TEXT NOT NULL,amount NUMERIC NOT NULL,reason TEXT NOT NULL,status TEXT NOT NULL DEFAULT 'PENDING',created_by TEXT NOT NULL,approved_by TEXT,approved_at TIMESTAMP,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE INDEX IF NOT EXISTS ix_mfg_cost_scope ON manufacturing_batch_cost(organization_id,entity_id,period_key,product_id);
